(()=>{const cfg=window.WP,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>'$'+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});let data=null,cart=new Map(),requestType='support',agentLoaded=false;const titles={overview:['Wholesale Overview','Orders, fulfillment, receivables, and next actions.'],catalog:['Wholesale Catalog','Account-specific products and pricing.'],orders:['Orders','Live production and fulfillment progress.'],invoices:['Invoices','Receivables, due dates, credits, and payments.'],quotes:['Quotes','Review and accept active proposals.'],requests:['Requests','Samples, products, delivery, and support.'],history:['History','Your Wholesale relationship timeline.'],agent:['Wholesale AI Agent','Private intelligence scoped only to your company.'],profile:['Business Profile','Keep your account preferences current.']};function toast(t){const e=$('toast');e.textContent=t;e.style.display='block';setTimeout(()=>e.style.display='none',2400)}async function api(url,opt={}){const r=await fetch(url,{cache:'no-store',headers:{Accept:'application/json',...(opt.body?{'Content-Type':'application/json','X-CSRF-Token':cfg.csrf}:{}),...(opt.headers||{})},...opt}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.message||'Request failed');return d}function go(p){document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+p));document.querySelectorAll('.nav button').forEach(x=>x.classList.toggle('active',x.dataset.page===p));$('pageTitle').textContent=titles[p][0];$('pageSubtitle').textContent=titles[p][1];if(p==='agent')loadAgent()}document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));
function itemText(items){return(items||[]).map(i=>[i.quantity,i.unit||i.sell_uom_snapshot,i.name||i.product||i.item||i.item_name_snapshot].filter(Boolean).join(' ')).join(' · ')}function statusChip(s,over=false){return`<span class="chip ${s==='paid'||s==='delivered'?'good':over?'warn':''}">${esc(s||'')}</span>`}function orderCard(o){const f=o.fulfillment||{},p=f.progress||{},invoice=o.invoice,canRepeat=o.status==='delivered';return`<article class="item"><div class="itemtop"><div><strong>${esc(o.order_number)}</strong><div class="muted">${esc(itemText(o.items))}</div></div><div style="text-align:right">${statusChip(o.status)}<strong class="money" style="display:block;margin-top:5px">${money(o.total)}</strong></div></div><div class="progress"><span style="width:${Number(p.deliveryPercent||0)}%"></span></div><div class="muted">Allocation ${Number(p.allocationPercent||0)}% · Delivery ${Number(p.deliveryPercent||0)}%${f.promisedWindowStart?' · Promised '+esc(f.promisedWindowStart):''}</div>${invoice?`<div class="muted">Invoice ${esc(invoice.number)} · ${statusChip(invoice.status,Number(invoice.daysOverdue)>0)} · balance ${money(invoice.balance)}</div>`:''}${canRepeat?`<button class="btn" data-repeat="${esc(o.public_id)}" style="margin-top:8px">Repeat this order</button>`:''}${(f.batches||[]).length?`<div class="list">${f.batches.map(b=>`<div class="item"><div class="itemtop"><strong>${esc(b.number)}</strong>${statusChip(b.status)}</div><div class="muted">${esc(itemText(b.items))}${b.promisedWindowStart?' · '+esc(b.promisedWindowStart):''}</div></div>`).join('')}</div>`:''}</article>`}function invoiceCard(i){return`<article class="item"><div class="itemtop"><div><strong>${esc(i.number)} · ${esc(i.orderNumber)}</strong><div class="muted">Issued ${esc(i.issueDate||'—')} · Due ${esc(i.dueDate||'—')}</div></div><div style="text-align:right">${statusChip(i.status,Number(i.daysOverdue)>0)}<strong class="money" style="display:block;margin-top:5px">${money(i.balance)} due</strong></div></div>${Number(i.daysOverdue)>0?`<div class="chip warn" style="margin-top:7px">${i.daysOverdue} days overdue</div>`:''}<div class="invoice-lines">${(i.items||[]).map(x=>`<div><span>${esc(x.quantity+' '+x.unit+' '+x.name)}</span><span>${money(x.lineSubtotal)}</span></div>`).join('')}<div><strong>Total</strong><strong>${money(i.total)}</strong></div></div>${(i.entries||[]).length?`<div class="list">${i.entries.map(e=>`<div class="item"><div class="itemtop"><strong>${esc(e.type)}</strong><small>${esc(e.effectiveDate)}</small></div><div class="muted">${money(e.amount)}${e.paymentMethod?' · '+esc(e.paymentMethod):''}${e.reference?' · '+esc(e.reference):''}</div></div>`).join('')}</div>`:''}</article>`}function quoteCard(q){return`<article class="item"><div class="itemtop"><div><strong>${esc(q.quote_number)}</strong><div class="muted">${esc(itemText(q.items))}</div></div><div style="text-align:right">${statusChip(q.status)}<strong class="money" style="display:block;margin-top:5px">${money(q.total)}</strong></div></div>${q.customer_message?`<p class="muted">${esc(q.customer_message)}</p>`:''}${q.valid_until?`<p class="muted">Valid through ${esc(q.valid_until)}</p>`:''}${q.status==='sent'?`<button class="btn primary" data-accept="${esc(q.public_id)}">Accept quote</button>`:''}</article>`}
function renderCatalog(){const rows=data.catalog||[];$('catalog').innerHTML=rows.length?rows.map(x=>{const qty=cart.get(x.id)||'';return`<article class="product"><div class="eyebrow">${esc(x.category||'Wholesale')}</div><h3>${esc(x.name)}</h3><div class="muted">SKU ${esc(x.sku)} · ${esc(x.sellUom)} · min ${Number(x.priceMinimumQuantity??x.minimumQuantity||0)} · step ${Number(x.quantityIncrement||1)}</div><div class="price">${money(x.unitPrice)} <span class="muted">/ ${esc(x.sellUom)}</span></div><div class="qtyrow"><input class="field catalogQty" data-id="${esc(x.id)}" type="number" min="0" step="${Number(x.quantityIncrement||1)}" value="${esc(qty)}" placeholder="Qty"><button class="btn dark catalogAdd" data-id="${esc(x.id)}">Set quantity</button></div></article>`}).join(''):'<div class="empty">No currently priced Wholesale SKUs are available for this account.</div>';document.querySelectorAll('.catalogAdd').forEach(b=>b.onclick=()=>{const input=document.querySelector(`.catalogQty[data-id="${CSS.escape(b.dataset.id)}"]`),v=Number(input.value||0);if(v>0)cart.set(b.dataset.id,v);else cart.delete(b.dataset.id);renderCart()});renderCart()}function renderCart(){let count=0,total=0;for(const[id,q]of cart){const x=(data.catalog||[]).find(v=>v.id===id);if(!x)continue;count+=q;total+=q*Number(x.unitPrice||0)}$('cartCount').textContent=count?`${count} unit${count===1?'':'s'} selected`:'0 items selected';$('cartSubtotal').textContent=money(total)}function render(){const a=data.account,s=data.summary||{},orders=data.orders||[],quotes=data.quotes||[],req=data.requests||[],inv=data.invoices||[];$('sStatus').textContent=a.account_status||'active';$('sOrders').textContent=orders.filter(o=>!['delivered','cancelled'].includes(o.status)).length;$('sAR').textContent=money(s.receivables);$('sOverdue').textContent=money(s.overdue);$('sCatalog').textContent=s.catalogItems||0;$('overviewOrders').innerHTML=orders.filter(o=>!['delivered','cancelled'].includes(o.status)).slice(0,5).map(orderCard).join('')||'<div class="empty">No active orders.</div>';$('orders').innerHTML=orders.map(orderCard).join('')||'<div class="empty">No orders yet.</div>';$('invoices').innerHTML=inv.map(invoiceCard).join('')||'<div class="empty">No invoices yet.</div>';$('quotes').innerHTML=quotes.map(quoteCard).join('')||'<div class="empty">No quotes yet.</div>';$('requests').innerHTML=req.map(r=>`<article class="item"><div class="itemtop"><strong>${esc(r.subject)}</strong>${statusChip(r.status)}</div><div class="muted">${esc(r.request_type)} · ${esc(r.created_at)}<br>${esc(r.details)}</div></article>`).join('')||'<div class="empty">No requests yet.</div>';$('history').innerHTML=(data.history||[]).map(e=>`<div class="event"><div class="dot"></div><div class="eventbody"><div class="itemtop"><strong>${esc(e.title)}</strong><small>${esc(e.at)}</small></div>${e.detail?`<div class="muted">${esc(e.detail)}</div>`:''}</div></div>`).join('')||'<div class="empty">No history yet.</div>';$('locations').innerHTML=(data.locations||[]).map(l=>`<div class="item"><strong>${esc(l.name)}</strong><div class="muted">${esc([l.address_line_1,l.address_line_2,l.city,l.state,l.postal_code].filter(Boolean).join(', '))}</div></div>`).join('')||'<div class="empty">No locations recorded.</div>';$('pPhone').value=a.phone||'';$('pWebsite').value=a.website||'';$('pBilling').value=a.billing_email||'';$('pFulfillment').value=a.preferred_fulfillment||'';$('pFlavors').value=a.flavor_preferences||'';try{$('pPackages').value=(JSON.parse(a.package_preferences_json||'[]')||[]).join(', ')}catch{$('pPackages').value=''}$('pNotes').value=a.customer_notes||'';$('pPrivate').checked=!!Number(a.private_label_interest);renderCatalog();bindDynamic()}
function bindDynamic(){document.querySelectorAll('[data-accept]').forEach(b=>b.onclick=async()=>{if(!confirm('Accept this quote and create an order request?'))return;try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'accept_quote',quoteId:b.dataset.accept,csrf_token:cfg.csrf})});toast(d.message);await load()}catch(e){alert(e.message)}});document.querySelectorAll('[data-repeat]').forEach(b=>b.onclick=async()=>{if(!confirm('Repeat this delivered order using current catalog pricing and the prior tax/delivery setup?'))return;try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'repeat_order',orderId:b.dataset.repeat,csrf_token:cfg.csrf})});toast(d.message);await load();go('orders')}catch(e){alert(e.message)}})}async function load(){data=await api('api/wholesale-portal.php');render()}
$('submitCatalog').onclick=async()=>{const items=[...cart].map(([skuId,quantity])=>({skuId,quantity}));if(!items.length){alert('Choose at least one catalog item.');return}try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'catalog_request',items,requestedFor:$('requestedFor').value,csrf_token:cfg.csrf})});toast(d.message);cart.clear();await load();go('requests')}catch(e){alert(e.message)}};
function openRequest(type){requestType=type;$('requestTitle').textContent={sample:'Sample request',product:'Product / pricing request',delivery:'Delivery request',support:'Wholesale support',reorder:'Reorder request'}[type]||'Wholesale request';$('rSubject').value='';$('rDetails').value='';$('requestModal').classList.add('open');$('rSubject').focus()}document.querySelectorAll('[data-open-request]').forEach(b=>b.onclick=()=>openRequest(b.dataset.openRequest));$('requestCancel').onclick=()=>$('requestModal').classList.remove('open');$('requestSend').onclick=async()=>{try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'request',requestType,subject:$('rSubject').value,details:$('rDetails').value,csrf_token:cfg.csrf})});$('requestModal').classList.remove('open');toast(d.message);await load();go('requests')}catch(e){alert(e.message)}};
$('profileForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('api/wholesale-portal.php',{method:'POST',body:JSON.stringify({action:'profile',phone:$('pPhone').value,website:$('pWebsite').value,billingEmail:$('pBilling').value,preferredFulfillment:$('pFulfillment').value,flavorPreferences:$('pFlavors').value,packagePreferences:$('pPackages').value.split(',').map(x=>x.trim()).filter(Boolean),customerNotes:$('pNotes').value,privateLabelInterest:$('pPrivate').checked,csrf_token:cfg.csrf})});toast(d.message);await load()}catch(err){alert(err.message)}};
function addMessage(role,text,meta=''){const m=document.createElement('div');m.className='message '+(role==='user'?'user':'');m.textContent=text;if(meta){const s=document.createElement('small');s.textContent=meta;m.appendChild(s)}$('messages').appendChild(m);$('messages').scrollTop=$('messages').scrollHeight}async function loadAgent(){if(agentLoaded)return;agentLoaded=true;try{const d=await api('api/wholesale-portal-agent.php');$('agentReady').textContent=d.ready?'AI connected · account-scoped':'Account skills available · open-ended AI not configured';$('messages').innerHTML='';if((d.history||[]).length)(d.history||[]).forEach(h=>addMessage(h.message_role,h.content,h.skill||''));else addMessage('assistant',`Welcome. I can help with ${d.businessName}'s orders, fulfillment, invoices, quotes, requests, and preferences.`,'wholesale_portal.agent')}catch(e){$('agentReady').textContent=e.message}}async function sendAgent(){const v=$('agentInput').value.trim();if(!v)return;addMessage('user',v);$('agentInput').value='';$('agentSend').disabled=true;try{const d=await api('api/wholesale-portal-agent.php',{method:'POST',body:JSON.stringify({message:v,csrf_token:cfg.csrf})});addMessage('assistant',d.reply,d.skill||'')}catch(e){addMessage('assistant',e.message)}finally{$('agentSend').disabled=false}}$('agentSend').onclick=sendAgent;$('agentInput').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendAgent()}};load().catch(e=>alert(e.message));})();
</script></body></html>